<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,ref,watch} from 'vue'
import {IconArrowRight,IconCheck,IconChevronDown,IconDots,IconFileText,IconGift,IconPlayerPause,IconPlayerPlay,IconPlus,IconScale,IconShieldCheck,IconSun,IconUnlink,IconX} from '@tabler/icons-vue'
import type {components} from '../../shared/api'
import type {SessionClient} from '../auth/session'
import {partnerId,scopeLabel,statusLabel} from '../workspace/context'
type S=components['schemas'];type Relation=S['RelationView']
const props=defineProps<{client:SessionClient;me:S['MemberView'];participants:S['ParticipantView'][];relations:Relation[];contextId:string;ru:boolean;active:boolean}>()
const emit=defineEmits<{select:[string];changed:[]}>()
const t=(en:string,ru:string)=>props.ru?ru:en
const name=(id:string)=>props.participants.find(p=>p.id===id)?.display_name??t('Participant','Участник')
const selected=computed(()=>props.relations.find(r=>r.id===props.contextId)??props.relations[0])
const partner=(r:Relation)=>name(partnerId(r,props.me.id)??'')
const scopeOptions=['rules.assign','rituals.assign','rituals.review','discipline.propose','discipline.review','rewards.grant']
const scopeIcons=[IconFileText,IconSun,IconCheck,IconScale,IconShieldCheck,IconGift]
const scopeTitles=[['Rules','Правила'],['Rituals','Ритуалы'],['Report review','Проверка отчётов'],['Assign punishments','Назначение наказаний'],['Punishment review','Проверка наказаний'],['Rewards','Награды']]
const scopeTitle=(scope:string)=>scopeTitles[scopeOptions.indexOf(scope)]?.[props.ru?1:0]??scopeLabel(scope,props.ru)
const busy=ref(false),error=ref(''),notice=ref(''),menu=ref<HTMLDetailsElement|null>(null),permissionsOpen=ref(true)
const dialog=ref<HTMLDialogElement|null>(null),editing=ref(false),target=ref(''),direction=ref('dominant'),agreement=ref(''),scopes=ref<string[]>(['rules.assign'])
const confirmation=ref<{relation:Relation;action:'accept'|'pause'|'resume'|'revoke'}|null>(null),confirmDialog=ref<HTMLDialogElement|null>(null)
function close(){if(!busy.value){if(editing.value){target.value='';direction.value='dominant';agreement.value='';scopes.value=['rules.assign']}editing.value=false;confirmation.value=null;error.value=''}}
function propose(){menu.value?.removeAttribute('open');error.value='';editing.value=true}
function request(action:'accept'|'pause'|'resume'|'revoke'){if(!selected.value)return;menu.value?.removeAttribute('open');error.value='';confirmation.value={relation:{...selected.value,scopes:[...selected.value.scopes],consent_user_ids:[...selected.value.consent_user_ids]},action}}
const actionTitle=computed(()=>confirmation.value?.action==='accept'?t('Accept this version','Подтвердить эту версию'):confirmation.value?.action==='pause'?t('Pause relationship','Приостановить отношения'):confirmation.value?.action==='resume'?t('Request resumption','Запросить возобновление'):t('Withdraw agreement','Отозвать соглашение'))
async function save(){if(busy.value)return;busy.value=true;error.value='';try{const relation=await props.client.post<Relation>('/relations',{dominant_user_id:direction.value==='dominant'?props.me.id:target.value,submissive_user_id:direction.value==='dominant'?target.value:props.me.id,scopes:scopes.value,agreement_text:agreement.value});editing.value=false;target.value='';agreement.value='';scopes.value=['rules.assign'];emit('changed');emit('select',relation.id);notice.value=t('Proposal sent. Both participants must accept this version.','Предложение отправлено. Оба участника должны подтвердить эту версию.')}catch{error.value=t('Could not send. Check the fields and try again.','Не удалось отправить. Проверьте поля и повторите.')}finally{busy.value=false}}
async function confirm(){const c=confirmation.value;if(!c||busy.value)return;busy.value=true;error.value='';try{await props.client.post(`/relations/${c.relation.id}/${c.action}`,{expected_version:c.relation.version,...(c.action==='accept'?{relation_version_id:c.relation.relation_version_id}:{})});confirmation.value=null;emit('changed');notice.value=t('Relationship updated.','Отношения обновлены.')}catch{error.value=t('The version changed or this action is unavailable. Close this window and review the latest agreement.','Версия изменилась или действие недоступно. Закройте окно и проверьте актуальное соглашение.');emit('changed')}finally{busy.value=false}}
watch(editing,async open=>{await nextTick();if(open)dialog.value?.showModal();else dialog.value?.close()})
watch(confirmation,async value=>{await nextTick();if(value)confirmDialog.value?.showModal();else confirmDialog.value?.close()})
watch(()=>props.active,value=>{if(value&&!props.contextId&&selected.value)emit('select',selected.value.id);if(!value){editing.value=false;confirmation.value=null;menu.value?.removeAttribute('open')}} ,{immediate:true})
watch(()=>props.contextId,()=>{menu.value?.removeAttribute('open');confirmation.value=null;notice.value=''})
onBeforeUnmount(()=>{dialog.value?.close();confirmDialog.value?.close()})
</script>
<template>
<section id="relations" class="relations-panel" :aria-label="t('Relationships','Отношения')">
 <div class="relations-strip"><div class="relations-partners" :aria-label="t('Choose relationship','Выбрать отношения')"><button v-for="r in relations" :key="r.id" type="button" class="relation-partner" :aria-pressed="selected?.id===r.id" :disabled="busy" @click="emit('select',r.id)"><span class="person-monogram" aria-hidden="true">{{partner(r).slice(0,1)}}</span><span><strong>{{partner(r)}}</strong><small class="relation-direction">{{name(r.dominant_user_id)}} <IconArrowRight :size="12"/> {{name(r.submissive_user_id)}}</small><small class="relation-status" :data-status="r.status">{{statusLabel(r.status,ru)}}</small></span></button></div><button class="relation-propose" :aria-label="t('Propose relationship','Предложить отношения')" :title="t('Propose relationship','Предложить отношения')" :disabled="busy||me.paused||!participants.some(p=>p.id!==me.id)" @click="propose"><IconPlus :size="18"/><span>{{t('Propose relationship','Предложить отношения')}}</span></button></div>
 <p v-if="notice" class="relation-notice" role="status">{{notice}}</p>
 <div v-if="selected" :key="selected.id" class="relation-overview">
  <div class="relation-main"><header class="relation-identity"><div class="relation-pair" aria-hidden="true"><span class="person-monogram">{{name(selected.dominant_user_id).slice(0,1)}}</span><IconArrowRight :size="22"/><span class="person-monogram partner-monogram">{{name(selected.submissive_user_id).slice(0,1)}}</span></div><div class="relation-names"><h2>{{name(selected.dominant_user_id)}} <IconArrowRight :size="20"/> {{name(selected.submissive_user_id)}}</h2><p><span>{{t('Upper','Верхний')}}</span><span>{{t('Lower','Нижний')}}</span></p></div><div class="relation-state-actions"><span class="status-tag" :data-status="selected.status">{{statusLabel(selected.status,ru)}}</span><div><button v-if="['active','proposed'].includes(selected.status)" class="icon-button" :disabled="busy" :aria-label="t('Pause relationship','Приостановить отношения')" :title="t('Pause relationship','Приостановить отношения')" @click="request('pause')"><IconPlayerPause :size="20"/></button><button v-if="selected.status==='paused'" class="icon-button" :disabled="busy||me.paused" :aria-label="t('Request resumption','Запросить возобновление')" :title="t('Request resumption','Запросить возобновление')" @click="request('resume')"><IconPlayerPlay :size="20"/></button><details v-if="selected.status!=='revoked'" ref="menu" class="relation-more"><summary :aria-label="t('Relationship actions','Действия с отношениями')"><IconDots :size="20"/></summary><div><button type="button" class="danger-button" :disabled="busy" @click="request('revoke')"><IconUnlink :size="17"/>{{t('Withdraw agreement','Отозвать соглашение')}}</button></div></details></div></div></header>
   <div class="relation-agreement"><h3>{{t('Agreement','Соглашение')}}</h3><p>{{selected.agreement_text}}</p><div class="relation-confirmations"><small>{{t('Version','Версия')}} {{selected.version}} · {{t('Confirmations','Подтверждения')}} {{selected.consent_user_ids.length}}/2</small></div><button v-if="selected.status==='proposed'&&!selected.consent_user_ids.includes(me.id)" :disabled="busy||me.paused" @click="request('accept')"><IconCheck :size="18"/>{{t('Review and accept','Рассмотреть и подтвердить')}}</button><p v-else-if="selected.status==='proposed'" class="muted">{{t('Awaiting the other participant’s confirmation.','Ожидаем подтверждения второго участника.')}}</p></div>
  </div>
  <aside class="relation-permissions"><button class="relation-permissions-heading" :aria-expanded="permissionsOpen" aria-controls="relation-permissions-list" @click="permissionsOpen=!permissionsOpen"><h3>{{t('Permissions','Полномочия')}}</h3><IconChevronDown :size="17" :class="{'is-open':permissionsOpen}"/></button><div id="relation-permissions-list" v-show="permissionsOpen"><div v-for="scope in selected.scopes" :key="scope" class="relation-permission"><component :is="scopeIcons[scopeOptions.indexOf(scope)]??IconShieldCheck" :size="25" :stroke-width="1.5"/><div><strong>{{scopeTitle(scope)}}</strong><small>{{scopeLabel(scope,ru)}}</small></div></div><p class="relation-scope-note">{{selected.status==='active'?t('Permissions apply only to this relationship.','Полномочия действуют только в этих отношениях.'):selected.status==='proposed'?t('Permissions start after both participants confirm.','Полномочия начнут действовать после подтверждения обоих участников.'):t('These permissions are currently inactive.','Сейчас эти полномочия не действуют.')}}</p></div></aside>
 </div><p v-else class="empty-state">{{t('No relationships yet. Send your first proposal.','Пока нет отношений. Отправьте первое предложение.')}}</p>
 <dialog ref="dialog" class="relation-dialog relation-editor" :aria-label="t('Propose relationship','Предложить отношения')" @cancel.prevent="close"><header><h3>{{t('Propose relationship','Предложить отношения')}}</h3><button class="icon-button" :disabled="busy" :aria-label="t('Close','Закрыть')" @click="close"><IconX :size="20"/></button></header><form v-if="editing" @submit.prevent="save"><label>{{t('Participant','Участник')}}<select v-model="target" required :disabled="busy"><option value="" disabled>{{t('Select participant','Выберите участника')}}</option><option v-for="p in participants.filter(p=>p.id!==me.id)" :key="p.id" :value="p.id">{{p.display_name}}</option></select></label><fieldset class="relation-direction-fields" :disabled="busy"><legend>{{t('My role in this relationship','Моя роль в этих отношениях')}}</legend><label><input v-model="direction" type="radio" value="dominant">{{t('Upper — I receive permissions','Верхний — полномочия получаю я')}}</label><label><input v-model="direction" type="radio" value="submissive">{{t('Lower — my partner receives permissions','Нижний — полномочия получает партнёр')}}</label></fieldset><fieldset :disabled="busy"><legend>{{t('Permissions','Полномочия')}}</legend><label v-for="scope in scopeOptions" :key="scope"><input v-model="scopes" type="checkbox" :value="scope">{{scopeLabel(scope,ru)}}</label></fieldset><label>{{t('Agreement text','Текст соглашения')}}<textarea v-model="agreement" required maxlength="10000" rows="4" :disabled="busy"/></label><p class="muted">{{t('Both participants separately accept this exact version before activation.','Для активации оба участника отдельно подтверждают именно эту версию.')}}</p><p v-if="error" role="alert">{{error}}</p><footer><button :disabled="busy||!target||!agreement.trim()||!scopes.length">{{busy?t('Sending…','Отправляем…'):t('Send proposal','Отправить предложение')}}</button><button type="button" class="quiet-button" :disabled="busy" @click="close">{{t('Cancel','Отмена')}}</button></footer></form></dialog>
 <dialog ref="confirmDialog" class="relation-dialog relation-confirm-dialog" :aria-label="actionTitle" @cancel.prevent="close"><header><h3>{{actionTitle}}</h3><button class="icon-button" :disabled="busy" :aria-label="t('Close','Закрыть')" @click="close"><IconX :size="20"/></button></header><template v-if="confirmation"><p>{{name(confirmation.relation.dominant_user_id)}} <IconArrowRight :size="16"/> {{name(confirmation.relation.submissive_user_id)}}</p><small>{{t('Version','Версия')}} {{confirmation.relation.version}}</small><template v-if="confirmation.action==='accept'"><p class="agreement-copy">{{confirmation.relation.agreement_text}}</p><ul><li v-for="scope in confirmation.relation.scopes" :key="scope">{{scopeLabel(scope,ru)}}</li></ul><p class="muted">{{t('You accept this exact version and permissions.','Вы подтверждаете именно эту версию и полномочия.')}}</p></template><p v-else class="muted">{{confirmation.action==='resume'?t('Resumption requires fresh confirmation from both participants.','Для возобновления нужны новые подтверждения обоих участников.'):confirmation.action==='pause'?t('Permissions will stop until the relationship is resumed.','Полномочия перестанут действовать до возобновления отношений.'):t('These permissions will be revoked.','Эти полномочия будут отозваны.')}}</p><p v-if="error" role="alert">{{error}}</p><footer><button :class="{'danger-button':confirmation.action==='revoke'}" :disabled="busy" @click="confirm">{{t('Confirm','Подтвердить')}}</button><button type="button" class="quiet-button" :disabled="busy" @click="close">{{t('Cancel','Отмена')}}</button></footer></template></dialog>
</section>
</template>
